// BAD: one query per company ("N+1")
var accounts = new GlideRecord('core_company');
accounts.query();
while (accounts.next()) {
    var inc = new GlideRecord('incident');
    inc.addQuery('company', accounts.getUniqueValue());
    inc.query(); // runs 500 times
}

var counts = {};
var incidents = new GlideRecord('incident');
incidents.addQuery('active', true);
incidents.query();
while (incidents.next()) {
    var id = incidents.getValue('company');
    counts[id] = (counts[id] || 0) + 1;
}

// WASTEFUL: full query runs just to check "any matches?"
gr.query();
if (gr.getRowCount() > 0) { ... }

// BETTER: database can stop at the first match
gr.setLimit(1);
gr.query();
if (gr.next()) { ... }

// FAST: GlideAggregate never pulls full row data
var ga = new GlideAggregate('incident');
ga.addQuery('priority', 1);
ga.addAggregate('COUNT');
ga.query();
if (ga.next()) {
    var count = ga.getAggregate('COUNT');
}
